data class Reservation(val seats: Int, val taken: Int)
sealed interface Booking { data class Ok(val ref: String) : Booking
                           data class Rejected(val reason: String) : Booking }
fun reserve(r: Reservation, requested: Int, ref: String): Booking =   // pure
    when {
        requested <= 0 -> Booking.Rejected("invalid seat count")
        r.taken + requested > r.seats -> Booking.Rejected("no capacity")
        else -> Booking.Ok(ref)
    }
